#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "2mm.h"

void init_array(
    int ni,
    int nj,
    int nk,
    int nl,
    double *alpha,
    double *beta,
    double A[16][22],
    double B[22][18],
    double C[18][24],
    double D[16][24]) {
    int i, j;

    *alpha = 1.5;
    *beta = 1.2;
    for (i = 0; i < ni; i++)
        for (j = 0; j < nk; j++)
            A[i][j] = (double)((i * j + 1) % ni) / ni;
    for (i = 0; i < nk; i++)
        for (j = 0; j < nj; j++)
            B[i][j] = (double)(i * (j + 1) % nj) / nj;
    for (i = 0; i < nj; i++)
        for (j = 0; j < nl; j++)
            C[i][j] = (double)((i * (j + 3) + 1) % nl) / nl;
    for (i = 0; i < ni; i++)
        for (j = 0; j < nl; j++)
            D[i][j] = (double)(i * (j + 2) % nk) / nk;
}

void print_array(int ni, int nl, double D[16][24]) {
    int i, j;

    fprintf(stderr, "==BEGIN DUMP_ARRAYS==\n");
    fprintf(stderr, "begin dump: %s", "D");
    for (i = 0; i < ni; i++)
        for (j = 0; j < nl; j++) {
            if ((i * ni + j) % 20 == 0)
                fprintf(stderr, "\n");
            fprintf(stderr, "%0.6lf ", D[i][j]);
        }
    fprintf(stderr, "\nend   dump: %s\n", "D");
    fprintf(stderr, "==END   DUMP_ARRAYS==\n");
}

int main() {

    int ni = 16;
    int nj = 18;
    int nk = 22;
    int nl = 24;

    double alpha;
    double beta;
    double tmp[16][18];
    double A[16][22];
    double B[22][18];
    double C[18][24];
    double D[16][24];

    init_array(ni, nj, nk, nl, &alpha, &beta, A, B, C, D);

    kernel_2mm(alpha, beta, tmp, A, B, C, D);

    print_array(ni, nl, D);

    return 0;
}
</INPUT_CODE name="2mm_tb.cpp">
